'use strict';
const VIEWS=['overview','topics','networks','questions','sources','methods'];
const state={view:'overview',data:null,analysisSha256:null,collection:null,reading:null,speech:null,speechError:null,topicStudy:'baseline',speechSelected:null,speechRepresentation:'lexical_full',speechQuery:'',speechStratum:'all',speechPage:1,query:'',corpus:'all',format:'all',page:1,variant:'content',networkCorpus:'all',threshold:0.25,selected:null,labels:false};
const app=document.querySelector('#app');
const dialog=document.querySelector('#source-dialog');
const detail=document.querySelector('#source-detail');
const live=document.querySelector('#live-status');
let previousFocus=null;
const arr=x=>Array.isArray(x)?x:[];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const number=(x,d=0)=>finite(x)?x.toLocaleString('en-US',{maximumFractionDigits:d}):'Not reported';
const human=x=>String(x??'Not reported').replaceAll('_',' ');
const name=c=>c==='ra'?'Ra Contact':c==='bashar'?'Bashar-related':human(c);
const numSum=values=>{const ok=values.filter(finite);return ok.length?ok.reduce((a,b)=>a+b,0):null;};
const average=values=>{const ok=values.filter(finite);return ok.length?ok.reduce((a,b)=>a+b,0)/ok.length:null;};
const date=x=>{if(!x)return'Not recorded';const s=String(x);return /^\d{4}-\d{2}-\d{2}(?:T|$)/.test(s)?s.slice(0,10):s;};
const bytes=x=>!finite(x)?'Not reported':x>=1e9?number(x/1e9,2)+' GB':x>=1e6?number(x/1e6,1)+' MB':number(x)+' B';
const extIcon='<svg class="external-icon" viewBox="0 0 12 12" aria-hidden="true" focusable="false"><path d="M3 9 9 3M3 3h6v6" fill="none" stroke="currentColor" stroke-width="1.2"/></svg>';
function safeUrl(value){try{const u=new URL(String(value));return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function sourceLink(href,label='Open publisher source'){const u=safeUrl(href);return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)}${extIcon}</a>`:'Source URL not reported';}
const badge=c=>`<span class="corpus-label ${c==='bashar'?'bashar':''}">${esc(name(c))}</span>`;
const option=(value,label,chosen)=>`<option value="${esc(value)}"${String(value)===String(chosen)?' selected':''}>${esc(label)}</option>`;
